// C++14 (loops allowed in constexpr functions)
#include <iostream>

constexpr int fact(int n) { return n <= 1 ? 1 : n * fact(n - 1); }

constexpr int steps(int n) {               // C++14: loops and locals OK
    int s = 0;
    for (int i = 0; i < n; ++i) s += i;
    return s;
}

int main() {
    static_assert(fact(5) == 120);         // proved at compile time
    constexpr int s = steps(5);            // computed at compile time
    std::cout << s << " " << fact(6) << "\n";   // 10 720
}

// C++17 (constexpr std::array mutation)
#include <array>
#include <iostream>

constexpr std::array<double, 6> ladder(double rate) {
    std::array<double, 6> df{};
    df[0] = 1.0;
    for (int n = 1; n < 6; ++n)
        df[n] = df[n - 1] / (1.0 + rate);
    return df;
}

int main() {
    constexpr auto df = ladder(0.05);               // baked into the binary
    static_assert(df[5] > 0.783 && df[5] < 0.784);  // df5 = 1/(1.05)^5
    for (double d : df) std::cout << d << " ";
}

// C++20 - consteval: no runtime fallback
#include <iostream>

consteval int square(int x) { return x * x; }

int main() {
    constexpr int s = square(5);   // OK: 25 at compile time
    std::cout << s << "\n";        // 25
    // int y = 5;
    // int bad = square(y);        // compile error: needs a constant expression
}

// C++20 - constinit: ordered before dynamic initialisation, still mutable
#include <iostream>

constinit int tickBudget = 1'000'000;

void doubleBudget() { tickBudget *= 2; }   // legal: constinit is not const

int main() {
    doubleBudget();
    std::cout << tickBudget << "\n";       // 2000000
}

guidedExercise.solution:
```cpp
// C++17
constexpr double cpow(double base, int exp) {
    double result = 1.0;
    double b = base;
    while (exp > 0) {
        if (exp % 2 == 1) result *= b;
        b *= b;            // square the base each round
        exp /= 2;
    }
    return result;
}

static_assert(cpow(1.05, 10) > 1.6288 && cpow(1.05, 10) < 1.6290);
```

Trace of `cpow(1.05, 10)`: exponent 10 is even, so $b = 1.05^2 = 1.1025$, exp = 5; odd, so result $= 1.1025$ and $b = 1.21550625$, exp = 2; even, $b = 1.4774554438$, exp = 1; odd, result $= 1.1025 \times 1.4774554438 = 1.6288946268$, exp = 0. So $(1.05)^{10} \approx \mathbf{1.628895}$.

Squaring needs about $\log_2 10 \approx 4$ rounds instead of 9 multiplications, and here all of it happened inside the compiler, so the binary holds only the constant.

independentExercise.solution:
```cpp
// C++17
constexpr std::array<double, 6> ladder4() {
    std::array<double, 6> df{};
    df[0] = 1.0;
    for (int n = 1; n < 6; ++n) df[n] = df[n - 1] / 1.04;
    return df;
}
static_assert(ladder4()[5] > 0.8219 && ladder4()[5] < 0.8220);
```

Discount factors: $df_1 = 0.961538$, $df_2 = 0.924556$, $df_3 = 0.888996$, $df_4 = 0.854804$, $df_5 = \mathbf{0.821927}$ (check: $1/1.2166529024 = 0.8219271$).

Changing `1.04` to `1.05` recomputes the whole table at compile time, and the assert, still expecting 0.8219-0.8220, now **fails the build**, because the true df5 is 0.783526. That failure is the point: the bound is a compiler-checked contract on the curve.

